package com.visualbanktags;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(VisualBankTagsConfig.GROUP)
public interface VisualBankTagsConfig extends Config
{
	String GROUP = "visual-bank-tags";

	@ConfigSection(
		name = "General",
		description = "Controls where bank tag visuals are shown.",
		position = 0
	)
	String generalSection = "general";

	@ConfigSection(
		name = "Loose Untagged Items",
		description = "Styles items without Bank Tags so loose items are easy to find.",
		position = 1
	)
	String untaggedSection = "untagged";

	@ConfigSection(
		name = "Sorted Tagged Items",
		description = "Styles items that already have Bank Tags and their tab color indicators.",
		position = 2
	)
	String taggedSection = "tagged";

	@ConfigItem(
		keyName = "overlayEnabled",
		name = "",
		description = "",
		hidden = true
	)
	default boolean overlayEnabled()
	{
		return true;
	}

	@ConfigItem(
		position = 0,
		keyName = "groupStorage",
		name = "Enable in Group Storage",
		description = "Show visual tag coverage in Group Storage",
		section = generalSection
	)
	default boolean groupStorage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "openingHintDismissed",
		name = "",
		description = "",
		hidden = true
	)
	default boolean openingHintDismissed()
	{
		return false;
	}

	@ConfigItem(
		position = 0,
		keyName = "untaggedEnabled",
		name = "Enabled",
		description = "Highlight items that are not assigned to any Bank Tags",
		section = untaggedSection
	)
	default boolean untaggedEnabled()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "untaggedBorder",
		name = "Border",
		description = "Draw a border around loose items",
		section = untaggedSection
	)
	default boolean untaggedBorder()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		position = 2,
		keyName = "untaggedBorderColor",
		name = "Border color",
		description = "Color used for the loose item border",
		section = untaggedSection
	)
	default Color untaggedBorderColor()
	{
		return new Color(0xFF, 0x20, 0x20, 0xDD);
	}

	@Range(
		min = 1,
		max = 8
	)
	@ConfigItem(
		position = 3,
		keyName = "untaggedBorderWidth",
		name = "Border width",
		description = "Thickness of the loose item border",
		section = untaggedSection
	)
	default double untaggedBorderWidth()
	{
		return 1;
	}

	@Range(
		min = 0,
		max = 16
	)
	@ConfigItem(
		position = 4,
		keyName = "untaggedPadding",
		name = "Padding",
		description = "Extra space around loose item border and fill",
		section = untaggedSection
	)
	default double untaggedPadding()
	{
		return 1.5;
	}

	@ConfigItem(
		position = 5,
		keyName = "untaggedFill",
		name = "Fill",
		description = "Draw a transparent color over loose items",
		section = untaggedSection
	)
	default boolean untaggedFill()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		position = 6,
		keyName = "untaggedFillColor",
		name = "Fill color",
		description = "Color used for the loose item fill",
		section = untaggedSection
	)
	default Color untaggedFillColor()
	{
		return new Color(0xFF, 0x00, 0x00, 0x44);
	}

	@ConfigItem(
		position = 0,
		keyName = "taggedEnabled",
		name = "Enabled",
		description = "Highlight items that already have one or more Bank Tags",
		section = taggedSection
	)
	default boolean taggedEnabled()
	{
		return false;
	}

	@ConfigItem(
		position = 1,
		keyName = "renderInTagTabs",
		name = "Enable inside Tags tabs",
		description = "Show sorted item visuals while viewing Bank Tags tabs",
		section = taggedSection
	)
	default boolean renderInTagTabs()
	{
		return false;
	}

	@ConfigItem(
		position = 2,
		keyName = "taggedBorder",
		name = "Border",
		description = "Draw tag-colored borders around sorted items",
		section = taggedSection
	)
	default boolean taggedBorder()
	{
		return true;
	}

	@Range(
		min = 1,
		max = 16
	)
	@ConfigItem(
		position = 3,
		keyName = "taggedAccentSize",
		name = "Border size",
		description = "Thickness of sorted item and tag tab borders",
		section = taggedSection
	)
	default double taggedAccentSize()
	{
		return 1;
	}

	@Range(
		min = 0,
		max = 16
	)
	@ConfigItem(
		position = 4,
		keyName = "taggedPadding",
		name = "Padding",
		description = "Extra space around sorted item border and fill",
		section = taggedSection
	)
	default double taggedPadding()
	{
		return 1.5;
	}

	@Range(
		min = 0,
		max = 255
	)
	@ConfigItem(
		position = 5,
		keyName = "taggedAccentOpacity",
		name = "Border opacity",
		description = "Opacity of tag-colored borders for sorted items and tag tabs",
		section = taggedSection
	)
	default int taggedAccentOpacity()
	{
		return 255;
	}

	@ConfigItem(
		position = 6,
		keyName = "taggedFill",
		name = "Fill",
		description = "Draw a transparent color over sorted items",
		section = taggedSection
	)
	default boolean taggedFill()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		position = 7,
		keyName = "taggedFillColor",
		name = "Fill color",
		description = "Color used for the sorted item fill",
		section = taggedSection
	)
	default Color taggedFillColor()
	{
		return new Color(0x00, 0xC8, 0xFF, 0x22);
	}

	@ConfigItem(
		position = 8,
		keyName = "tagTabIndicators",
		name = "Tag tab indicators",
		description = "Show each Bank Tags tab's assigned color on its tab icon",
		section = taggedSection
	)
	default boolean tagTabIndicators()
	{
		return true;
	}

	@ConfigItem(
		position = 9,
		keyName = "customTagColors",
		name = "Tag Colors",
		description = "One color per line using tag:#RRGGBB. Use backslash for a literal colon in tag names, like loot\\:rares:#00c8ff",
		section = taggedSection
	)
	default String customTagColors()
	{
		return "";
	}
}

package com.visualbanktags;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Rectangle2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class VisualBankTagsOverlay extends Overlay
{
	private static final int CLIP_TOP_EXPANSION = 4;

	private final Client client;
	private final VisualBankTagsPlugin plugin;
	private final VisualBankTagsConfig config;

	@Inject
	VisualBankTagsOverlay(Client client, VisualBankTagsPlugin plugin, VisualBankTagsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		renderContainer(graphics, client.getWidget(InterfaceID.Bankmain.UNIVERSE), client.getWidget(InterfaceID.Bankmain.ITEMS), InventoryID.BANK);
		renderContainer(graphics, client.getWidget(InterfaceID.SharedBank.MAIN_BANK), client.getWidget(InterfaceID.SharedBank.ITEMS), InventoryID.GROUP_STORAGE);
		return null;
	}

	private void renderContainer(Graphics2D graphics, Widget root, Widget container, InventoryID inventoryID)
	{
		if (root == null || root.isHidden() || container == null || container.isHidden())
		{
			return;
		}

		ItemContainer itemContainer = client.getItemContainer(inventoryID);
		if (itemContainer == null)
		{
			return;
		}

		Widget[] children = container.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			children = container.getChildren();
		}
		if (children == null)
		{
			return;
		}

		for (Widget widget : children)
		{
			renderWidget(graphics, widget, itemContainer);
		}
	}

	private void renderWidget(Graphics2D graphics, Widget widget, ItemContainer itemContainer)
	{
		if (widget == null || widget.isHidden() || widget.isSelfHidden())
		{
			return;
		}

		int itemId = widget.getItemId();
		if (!plugin.shouldRenderItemVisuals(widget) || !plugin.isValidBankItem(itemId) || !hasVisibleItem(itemContainer, itemId) || plugin.isBankTagWidget(widget))
		{
			return;
		}

		Rectangle bounds = widget.getBounds();
		if (bounds.isEmpty())
		{
			return;
		}

		Rectangle viewportBounds = getViewportBounds(widget);
		List<String> tags = plugin.getBankTags(itemId);
		Shape clip = graphics.getClip();
		if (viewportBounds != null && !viewportBounds.isEmpty())
		{
			viewportBounds = new Rectangle(viewportBounds);
			viewportBounds.y -= CLIP_TOP_EXPANSION;
			viewportBounds.height += CLIP_TOP_EXPANSION;
			graphics.clip(viewportBounds);
		}
		try
		{
			if (tags.isEmpty())
			{
				renderUntagged(graphics, bounds);
			}
			else
			{
				renderTagged(graphics, bounds, tags);
			}
		}
		finally
		{
			graphics.setClip(clip);
		}
	}

	private boolean hasVisibleItem(ItemContainer itemContainer, int itemId)
	{
		for (Item item : itemContainer.getItems())
		{
			if (item != null && item.getId() == itemId && item.getQuantity() > 0)
			{
				return true;
			}
		}
		return false;
	}

	private void renderUntagged(Graphics2D graphics, Rectangle bounds)
	{
		if (!config.untaggedEnabled())
		{
			return;
		}

		if (config.untaggedFill())
		{
			drawFill(graphics, bounds, config.untaggedFillColor(), config.untaggedPadding());
		}
		if (config.untaggedBorder())
		{
			drawBorder(graphics, bounds, config.untaggedBorderColor(), config.untaggedBorderWidth(), config.untaggedPadding());
		}
	}

	private void renderTagged(Graphics2D graphics, Rectangle bounds, List<String> tags)
	{
		if (!config.taggedEnabled())
		{
			return;
		}

		if (config.taggedFill())
		{
			drawFill(graphics, bounds, config.taggedFillColor(), config.taggedPadding());
		}
		if (config.taggedBorder())
		{
			drawTagBorder(graphics, bounds, tags);
		}
	}

	private void drawFill(Graphics2D graphics, Rectangle bounds, Color color, double padding)
	{
		Rectangle2D fillBounds = paddedBounds(bounds, padding, false);
		if (fillBounds == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.fill(fillBounds);
	}

	private void drawBorder(Graphics2D graphics, Rectangle bounds, Color color, double width, double padding)
	{
		Rectangle2D borderBounds = paddedBounds(bounds, padding, true);
		if (borderBounds == null)
		{
			return;
		}

		Stroke stroke = graphics.getStroke();
		graphics.setStroke(new BasicStroke((float) plugin.steppedBorderSize(width)));
		graphics.setColor(color);
		graphics.draw(borderBounds);
		graphics.setStroke(stroke);
	}

	private void drawTagBorder(Graphics2D graphics, Rectangle bounds, List<String> tags)
	{
		plugin.drawTagBorder(graphics, bounds, tags, config.taggedAccentSize(), config.taggedPadding(), config.taggedAccentOpacity());
	}

	private Rectangle2D paddedBounds(Rectangle bounds, double padding, boolean border)
	{
		double expansion = Math.max(0, padding);
		double adjustment = border ? 1 : 0;
		double width = bounds.width - adjustment + expansion * 2;
		double height = bounds.height - adjustment + expansion * 2;
		if (width <= 0 || height <= 0)
		{
			return null;
		}

		return new Rectangle2D.Double(bounds.x - expansion, bounds.y - expansion, width, height);
	}

	private Rectangle getViewportBounds(Widget widget)
	{
		Rectangle viewport = null;
		for (Widget current = widget.getParent(); current != null; current = current.getParent())
		{
			Rectangle bounds = current.getBounds();
			if (bounds.width <= 0 || bounds.height <= 0)
			{
				continue;
			}

			viewport = viewport == null ? new Rectangle(bounds) : viewport.intersection(bounds);
			if (viewport.isEmpty())
			{
				return viewport;
			}
		}

		return viewport;
	}
}

package com.visualbanktags;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Visual Bank Tags",
	description = "Find items which have no tags with ease, and more to keep your bank tidy!",
	tags = {"visual bank tags", "visual tags", "loose bank tags", "loose items", "bank tags", "bank", "tags", "tagged", "untagged", "loose", "highlight", "overlay", "organize", "organisation", "organization"}
)
public class VisualBankTagsPlugin extends Plugin
{
	private static final String BANK_TAGS_GROUP = "banktags";
	private static final String BANK_TAGS_ITEM_PREFIX = "item_";
	private static final String BANK_TAGS_TAB_KEY = "tagtabs";
	private static final String CONFIG_TOGGLE_KEY = "overlayEnabled";
	private static final String CONFIG_LEGACY_TIP_KEY = "showToggleTip";
	private static final String CONFIG_HINT_DISMISSED_KEY = "openingHintDismissed";
	private static final String CONFIG_CUSTOM_COLORS_KEY = "customTagColors";
	private static final String CONFIG_UNTAGGED_BORDER_WIDTH_KEY = "untaggedBorderWidth";
	private static final String CONFIG_TAGGED_ACCENT_SIZE_KEY = "taggedAccentSize";
	private static final double BORDER_STEP = 0.25;
	private static final Color[] TAG_PALETTE = {
		new Color(0x00, 0xC8, 0xFF),
		new Color(0xFF, 0x4D, 0x4D),
		new Color(0x39, 0xB5, 0x4A),
		new Color(0xB8, 0x7C, 0xFF),
		new Color(0xFF, 0xC8, 0x2E),
		new Color(0x2F, 0x6D, 0xFF),
		new Color(0x8A, 0x5A, 0x1F),
		new Color(0xFF, 0x75, 0xC8),
		new Color(0x11, 0x8C, 0x8C),
		new Color(0xD6, 0xE8, 0x4A),
		new Color(0x7A, 0x32, 0xCC),
		new Color(0xFF, 0x7A, 0x45),
		new Color(0xE8, 0xE8, 0xE8),
		new Color(0x4A, 0x4A, 0x4A),
		new Color(0xA8, 0xD4, 0x63),
		new Color(0xC4, 0x2F, 0x2F)
	};
	private final Map<Integer, List<String>> tagCache = new HashMap<>();
	private final LinkedHashSet<String> knownTags = new LinkedHashSet<>();
	private Map<String, Color> customTagColors = new LinkedHashMap<>();
	private String customTagColorsSource = null;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private VisualBankTagsConfig config;

	@Inject
	private VisualBankTagsOverlay overlay;

	@Inject
	private VisualBankTagsTipOverlay tipOverlay;

	@Inject
	private VisualBankTagsTabOverlay tabOverlay;

	@Provides
	VisualBankTagsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VisualBankTagsConfig.class);
	}

	@Override
	protected void startUp()
	{
		tagCache.clear();
		refreshKnownTags();
		configManager.unsetConfiguration(VisualBankTagsConfig.GROUP, CONFIG_LEGACY_TIP_KEY);
		ensureGeneratedCustomTagColors();
		overlayManager.add(overlay);
		overlayManager.add(tipOverlay);
		overlayManager.add(tabOverlay);
		mouseManager.registerMouseListener(tipOverlay);
	}

	@Override
	protected void shutDown()
	{
		tagCache.clear();
		knownTags.clear();
		customTagColors = new LinkedHashMap<>();
		customTagColorsSource = null;
		overlayManager.remove(overlay);
		overlayManager.remove(tipOverlay);
		overlayManager.remove(tabOverlay);
		mouseManager.unregisterMouseListener(tipOverlay);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (event.getActionParam1() != InterfaceID.Bankmain.MENU_BUTTON)
		{
			return;
		}

		addToggleEntry();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BANK_TAGS_GROUP.equals(event.getGroup()))
		{
			tagCache.clear();
			syncCustomTagColorRename(event);
			refreshKnownTags();
			ensureGeneratedCustomTagColors();
		}
		else if (VisualBankTagsConfig.GROUP.equals(event.getGroup()) && CONFIG_CUSTOM_COLORS_KEY.equals(event.getKey()))
		{
			customTagColorsSource = null;
			ensureGeneratedCustomTagColors();
		}
		else if (VisualBankTagsConfig.GROUP.equals(event.getGroup()) && isBorderSizeKey(event.getKey()))
		{
			snapBorderSizeConfig(event);
		}
	}

	boolean isValidBankItem(int itemId)
	{
		return itemId > 0 && itemId != ItemID.BANK_FILLER;
	}

	boolean shouldRenderItemVisuals()
	{
		return config.overlayEnabled() && (config.renderInTagTabs() || !isBankTagViewOpen());
	}

	boolean shouldRenderItemVisuals(Widget widget)
	{
		return shouldRenderItemVisuals() && (config.groupStorage() || !isGroupStorageWidget(widget));
	}

	boolean isBankTagWidget(Widget widget)
	{
		if (widget == null || widget.getItemId() <= 0)
		{
			return false;
		}

		String name = widget.getName();
		if (name == null)
		{
			return false;
		}

		String tag = Text.standardize(Text.removeTags(name).trim());
		return !tag.isEmpty() && isKnownTag(tag);
	}

	List<String> getBankTags(int itemId)
	{
		if (!isValidBankItem(itemId))
		{
			return new ArrayList<>();
		}

		int canonicalId = itemManager.canonicalize(Math.abs(itemId));
		return tagCache.computeIfAbsent(canonicalId, this::loadBankTags);
	}

	private boolean isGroupStorageWidget(Widget widget)
	{
		return widget != null && componentGroup(widget.getId()) == componentGroup(InterfaceID.SharedBank.ITEMS);
	}

	private int componentGroup(int id)
	{
		return id >>> 16;
	}

	boolean shouldShowToggleTip()
	{
		return !config.openingHintDismissed() && isBankOpen();
	}

	void hideToggleTipForever()
	{
		configManager.setConfiguration(VisualBankTagsConfig.GROUP, CONFIG_HINT_DISMISSED_KEY, true);
	}

	boolean isKnownTag(String tag)
	{
		return knownTags.contains(Text.standardize(tag));
	}

	Color colorForTag(String tag, int alpha)
	{
		String standardizedTag = Text.standardize(tag);
		Color color = getCustomTagColors().get(standardizedTag);
		if (color == null)
		{
			color = defaultColorForTag(standardizedTag);
		}

		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
	}

	double steppedBorderSize(double value)
	{
		return Math.max(BORDER_STEP, Math.round(value / BORDER_STEP) * BORDER_STEP);
	}

	private boolean isBorderSizeKey(String key)
	{
		return CONFIG_UNTAGGED_BORDER_WIDTH_KEY.equals(key) || CONFIG_TAGGED_ACCENT_SIZE_KEY.equals(key);
	}

	private void snapBorderSizeConfig(ConfigChanged event)
	{
		if (event.getNewValue() == null)
		{
			return;
		}

		try
		{
			double value = Double.parseDouble(event.getNewValue());
			double oldValue = event.getOldValue() == null ? value : Double.parseDouble(event.getOldValue());
			double snapped = directionalBorderStep(oldValue, value);
			if (Math.abs(value - snapped) < 0.0001)
			{
				return;
			}

			configManager.setConfiguration(VisualBankTagsConfig.GROUP, event.getKey(), formatBorderStep(snapped));
		}
		catch (NumberFormatException ignored)
		{
		}
	}

	private double directionalBorderStep(double oldValue, double value)
	{
		if (value > oldValue)
		{
			return Math.ceil(value / BORDER_STEP) * BORDER_STEP;
		}
		if (value < oldValue)
		{
			return Math.floor(value / BORDER_STEP) * BORDER_STEP;
		}
		return steppedBorderSize(value);
	}

	private String formatBorderStep(double value)
	{
		double stepped = steppedBorderSize(value);
		if (stepped == Math.rint(stepped))
		{
			return Integer.toString((int) stepped);
		}
		return Double.toString(stepped);
	}

	void drawTagBorder(Graphics2D graphics, Rectangle bounds, List<String> tags, double size, double padding, int alpha)
	{
		if (tags.isEmpty())
		{
			return;
		}

		double expansion = Math.max(0, padding);
		double x = bounds.x - expansion;
		double y = bounds.y - expansion;
		double width = bounds.width + expansion * 2;
		double height = bounds.height + expansion * 2;
		if (width <= 0 || height <= 0)
		{
			return;
		}

		Object antialias = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		try
		{
			double borderSize = Math.max(BORDER_STEP, Math.min(steppedBorderSize(size), Math.min(width, height) / 2.0));
			drawHorizontalTagBorder(graphics, x, y, width, borderSize, tags, alpha);
			drawHorizontalTagBorder(graphics, x, y + height - borderSize, width, borderSize, tags, alpha);
			drawVerticalTagBorder(graphics, x, y, borderSize, height, tags, alpha);
			drawVerticalTagBorder(graphics, x + width - borderSize, y, borderSize, height, tags, alpha);
		}
		finally
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialias == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : antialias);
		}
	}

	private void drawHorizontalTagBorder(Graphics2D graphics, double x, double y, double width, double height, List<String> tags, int alpha)
	{
		for (int i = 0; i < tags.size(); i++)
		{
			double segmentX = x + width * i / tags.size();
			double nextX = x + width * (i + 1) / tags.size();
			graphics.setColor(colorForTag(tags.get(i), alpha));
			graphics.fill(new Rectangle2D.Double(segmentX, y, nextX - segmentX, height));
		}
	}

	private void drawVerticalTagBorder(Graphics2D graphics, double x, double y, double width, double height, List<String> tags, int alpha)
	{
		for (int i = 0; i < tags.size(); i++)
		{
			double segmentY = y + height * i / tags.size();
			double nextY = y + height * (i + 1) / tags.size();
			graphics.setColor(colorForTag(tags.get(i), alpha));
			graphics.fill(new Rectangle2D.Double(x, segmentY, width, nextY - segmentY));
		}
	}

	private void addToggleEntry()
