	private void toggleHighlight()
	{
		configManager.setConfiguration(VisualBankTagsConfig.GROUP, CONFIG_TOGGLE_KEY, !config.overlayEnabled());
	}

	private boolean isBankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	boolean isBankTagViewOpen()
	{
		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (title == null)
		{
			return false;
		}

		String text = title.getText();
		return text != null && Text.removeTags(text).trim().toLowerCase().startsWith("tag tab");
	}

	private List<String> loadBankTags(int canonicalId)
	{
		LinkedHashSet<String> tags = new LinkedHashSet<>();
		addTags(tags, canonicalId);

		int variationId = ItemVariationMapping.map(canonicalId);
		if (variationId > 0)
		{
			addTags(tags, -variationId);
		}

		return new ArrayList<>(tags);
	}

	private void addTags(LinkedHashSet<String> tags, int itemId)
	{
		String value = configManager.getConfiguration(BANK_TAGS_GROUP, BANK_TAGS_ITEM_PREFIX + itemId);
		if (value != null && !value.trim().isEmpty())
		{
			tags.addAll(Text.fromCSV(value.toLowerCase()));
		}
	}

	private void refreshKnownTags()
	{
		knownTags.clear();
		knownTags.addAll(collectBankTags());
	}

	private LinkedHashSet<String> collectBankTags()
	{
		LinkedHashSet<String> tags = new LinkedHashSet<>();
		addTagsFromConfigValue(tags, configManager.getConfiguration(BANK_TAGS_GROUP, BANK_TAGS_TAB_KEY));
		String prefix = BANK_TAGS_GROUP + "." + BANK_TAGS_ITEM_PREFIX;
		for (String key : configManager.getConfigurationKeys(prefix))
		{
			if (!key.startsWith(BANK_TAGS_GROUP + "."))
			{
				continue;
			}

			String value = configManager.getConfiguration(BANK_TAGS_GROUP, key.substring(BANK_TAGS_GROUP.length() + 1));
			addTagsFromConfigValue(tags, value);
		}
		return tags;
	}

	private void addTagsFromConfigValue(Collection<String> tags, String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return;
		}

		for (String tag : Text.fromCSV(value.toLowerCase()))
		{
			String standardized = Text.standardize(tag);
			if (!standardized.isEmpty())
			{
				tags.add(standardized);
			}
		}
	}

	private Map<String, Color> getCustomTagColors()
	{
		String value = config.customTagColors();
		if (value.equals(customTagColorsSource))
		{
			return customTagColors;
		}

		customTagColorsSource = value;
		customTagColors = parseCustomTagColors(value);
		return customTagColors;
	}

	private Map<String, Color> parseCustomTagColors(String value)
	{
		Map<String, Color> colors = new LinkedHashMap<>();
		for (String entry : splitCustomColorEntries(value))
		{
			int separator = findUnescapedColon(entry);
			if (separator <= 0)
			{
				continue;
			}

			String tag = Text.standardize(unescapeCustomText(entry.substring(0, separator)));
			Color color = parseColor(entry.substring(separator + 1));
			if (!tag.isEmpty() && color != null)
			{
				colors.put(tag, color);
			}
		}
		return colors;
	}

	private List<String> splitCustomColorEntries(String value)
	{
		List<String> entries = new ArrayList<>();
		StringBuilder entry = new StringBuilder();
		boolean escaped = false;
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			if (escaped)
			{
				entry.append('\\').append(c);
				escaped = false;
				continue;
			}
			if (c == '\\')
			{
				escaped = true;
				continue;
			}
			if (c == '\n' || c == '\r')
			{
				addCustomColorEntry(entries, entry);
				if (c == '\r' && i + 1 < value.length() && value.charAt(i + 1) == '\n')
				{
					i++;
				}
				continue;
			}
			entry.append(c);
		}
		if (escaped)
		{
			entry.append('\\');
		}
		addCustomColorEntry(entries, entry);
		return entries;
	}

	private void addCustomColorEntry(List<String> entries, StringBuilder entry)
	{
		String value = entry.toString().trim();
		if (!value.isEmpty())
		{
			entries.add(value);
		}
		entry.setLength(0);
	}

	private int findUnescapedColon(String value)
	{
		boolean escaped = false;
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			if (escaped)
			{
				escaped = false;
				continue;
			}
			if (c == '\\')
			{
				escaped = true;
				continue;
			}
			if (c == ':')
			{
				return i;
			}
		}
		return -1;
	}

	private String unescapeCustomText(String value)
	{
		StringBuilder builder = new StringBuilder();
		boolean escaped = false;
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			if (escaped)
			{
				builder.append(c == 'n' ? '\n' : c);
				escaped = false;
				continue;
			}
			if (c == '\\')
			{
				escaped = true;
				continue;
			}
			builder.append(c);
		}
		if (escaped)
		{
			builder.append('\\');
		}
		return builder.toString();
	}

	private void ensureGeneratedCustomTagColors()
	{
		if (knownTags.isEmpty())
		{
			return;
		}

		Map<String, Color> colors = new LinkedHashMap<>(getCustomTagColors());
		Map<String, Color> orderedColors = new LinkedHashMap<>();
		int index = 0;
		for (String tag : knownTags)
		{
			Color color = colors.get(tag);
			if (color == null)
			{
				color = TAG_PALETTE[index % TAG_PALETTE.length];
			}
			orderedColors.put(tag, color);
			index++;
		}
		for (Map.Entry<String, Color> entry : colors.entrySet())
		{
			if (!orderedColors.containsKey(entry.getKey()))
			{
				orderedColors.put(entry.getKey(), entry.getValue());
			}
		}
		if (!orderedColors.equals(colors))
		{
			saveCustomTagColors(orderedColors);
		}
	}

	private Color defaultColorForTag(String tag)
	{
		String standardizedTag = Text.standardize(tag);
		int index = 0;
		for (String knownTag : knownTags)
		{
			if (knownTag.equals(standardizedTag))
			{
				return TAG_PALETTE[index % TAG_PALETTE.length];
			}
			index++;
		}
		return TAG_PALETTE[Math.floorMod(standardizedTag.hashCode(), TAG_PALETTE.length)];
	}

	private Color parseColor(String value)
	{
		String hex = value.trim();
		if (hex.startsWith("#"))
		{
			hex = hex.substring(1);
		}
		if (hex.length() != 6 && hex.length() != 8)
		{
			return null;
		}

		try
		{
			int red = Integer.parseInt(hex.substring(0, 2), 16);
			int green = Integer.parseInt(hex.substring(2, 4), 16);
			int blue = Integer.parseInt(hex.substring(4, 6), 16);
			return new Color(red, green, blue);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private void syncCustomTagColorRename(ConfigChanged event)
	{
		if (!BANK_TAGS_TAB_KEY.equals(event.getKey()))
		{
			return;
		}

		Map<String, Color> colors = getCustomTagColors();
		if (colors.isEmpty())
		{
			return;
		}

		Set<String> oldTags = new HashSet<>();
		Set<String> newTags = new HashSet<>();
		addTagsFromConfigValue(oldTags, event.getOldValue());
		addTagsFromConfigValue(newTags, event.getNewValue());
		if (moveSingleCustomColor(oldTags, newTags, colors))
		{
			return;
		}

		Set<String> currentTags = collectBankTags();
		Set<String> removedCustomTags = new HashSet<>(knownTags);
		removedCustomTags.retainAll(colors.keySet());
		removedCustomTags.removeAll(currentTags);

		Set<String> addedTags = new HashSet<>(currentTags);
		addedTags.removeAll(knownTags);
		addedTags.removeAll(colors.keySet());

		moveSingleCustomColor(removedCustomTags, addedTags, colors);
	}

	private boolean moveSingleCustomColor(Set<String> oldTags, Set<String> newTags, Map<String, Color> colors)
	{
		Set<String> removed = new HashSet<>(oldTags);
		removed.removeAll(newTags);
		removed.retainAll(colors.keySet());

		Set<String> added = new HashSet<>(newTags);
		added.removeAll(oldTags);
		added.removeAll(colors.keySet());

		if (removed.size() == 1 && added.size() == 1)
		{
			moveCustomTagColor(removed.iterator().next(), added.iterator().next(), colors);
			return true;
		}

		return false;
	}

	private void moveCustomTagColor(String oldTag, String newTag, Map<String, Color> colors)
	{
		Map<String, Color> moved = new LinkedHashMap<>();
		for (Map.Entry<String, Color> entry : colors.entrySet())
		{
			moved.put(entry.getKey().equals(oldTag) ? newTag : entry.getKey(), entry.getValue());
		}

		saveCustomTagColors(moved);
	}

	private void saveCustomTagColors(Map<String, Color> colors)
	{
		StringBuilder builder = new StringBuilder();
		for (Map.Entry<String, Color> entry : colors.entrySet())
		{
			if (builder.length() > 0)
			{
				builder.append('\n');
			}
			builder.append(escapeCustomTag(entry.getKey())).append(':').append(formatColor(entry.getValue()));
		}

		configManager.setConfiguration(VisualBankTagsConfig.GROUP, CONFIG_CUSTOM_COLORS_KEY, builder.toString());
		customTagColorsSource = null;
	}

	private String escapeCustomTag(String value)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			switch (c)
			{
				case '\\':
				case ':':
					builder.append('\\').append(c);
					break;
				case '\n':
				case '\r':
					builder.append("\\n");
					break;
				default:
					builder.append(c);
					break;
			}
		}
		return builder.toString();
	}

	private String formatColor(Color color)
	{
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}
}

package com.visualbanktags;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.Text;

public class VisualBankTagsTabOverlay extends Overlay
{
	private static final int SIDE_TAB_CHILD_OFFSET = 4;

	private final Client client;
	private final VisualBankTagsPlugin plugin;
	private final VisualBankTagsConfig config;

	@Inject
	VisualBankTagsTabOverlay(Client client, VisualBankTagsPlugin plugin, VisualBankTagsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overlayEnabled() || !config.taggedEnabled() || !config.taggedBorder() || !config.tagTabIndicators())
		{
			return null;
		}

		boolean renderInTagTabs = config.renderInTagTabs();
		if (!plugin.isBankTagViewOpen() || renderInTagTabs)
		{
			renderSideTabs(graphics);
		}
		if (renderInTagTabs)
		{
			renderTagTabTab(graphics);
		}

		return null;
	}

	private void renderSideTabs(Graphics2D graphics)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (container == null || container.getChildren() == null)
		{
			return;
		}

		Widget[] children = container.getChildren();
		for (int i = SIDE_TAB_CHILD_OFFSET + 1; i < children.length; i += 2)
		{
			renderTagWidget(graphics, children[i]);
		}
	}

	private void renderTagTabTab(Graphics2D graphics)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.getChildren() == null)
		{
			return;
		}

		for (Widget child : container.getChildren())
		{
			renderTagWidget(graphics, child);
		}
	}

	private void renderTagWidget(Graphics2D graphics, Widget widget)
	{
		if (widget == null || widget.isHidden() || widget.getItemId() <= 0)
		{
			return;
		}

		String name = widget.getName();
		if (name == null)
		{
			return;
		}

		String tag = Text.standardize(Text.removeTags(name).trim());
		if (tag.isEmpty() || !plugin.isKnownTag(tag))
		{
			return;
		}

		plugin.drawTagBorder(graphics, widget.getBounds(), java.util.Collections.singletonList(tag), config.taggedAccentSize(), config.taggedPadding(), config.taggedAccentOpacity());
	}
}

