public class VisualBankTagsTipOverlay extends Overlay implements MouseListener
{
	private static final int WIDTH = 292;
	private static final int HEIGHT = 104;
	private static final int HEADER_HEIGHT = 30;
	private static final Color BACKGROUND = new Color(0x46, 0x3B, 0x2E, 0xF2);
	private static final Color ACCENT = new Color(0xE9, 0xBF, 0x6F);
	private static final Color BORDER_DARK = new Color(0x08, 0x06, 0x04, 0xEE);
	private static final Color BORDER_LIGHT = new Color(0x71, 0x64, 0x51, 0xE8);
	private static final Color TITLE = new Color(0xFF, 0xD8, 0x8A);
	private static final Color TEXT = new Color(0xEF, 0xE4, 0xD1);
	private static final Color BUTTON = new Color(0x5E, 0x50, 0x3D, 0xF2);

	private final Client client;
	private final VisualBankTagsPlugin plugin;
	private Rectangle panelBounds = new Rectangle();
	private Rectangle titleBarBounds = new Rectangle();
	private Rectangle closeButtonBounds = new Rectangle();
	private volatile boolean rendered;
	private boolean dragging;
	private Point dragOffset = new Point();

	@Inject
	VisualBankTagsTipOverlay(Client client, VisualBankTagsPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DETACHED);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(OverlayPriority.HIGHEST);
		setPreferredSize(new Dimension(WIDTH, HEIGHT));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldShowToggleTip())
		{
			setRendered(false);
			return null;
		}

		if (getPreferredLocation() == null)
		{
			Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
			if (bank != null)
			{
				Rectangle bounds = bank.getBounds();
				setPreferredLocation(new Point(bounds.x + 8, bounds.y + 48));
			}
			setRendered(false);
			return null;
		}

		drawBankButtonPulse(graphics);
		drawPanel(graphics);
		Point origin = getBounds().getLocation();
		panelBounds = new Rectangle(origin.x, origin.y, WIDTH, HEIGHT);
		titleBarBounds = new Rectangle(origin.x, origin.y, WIDTH, HEADER_HEIGHT);
		closeButtonBounds = new Rectangle(origin.x + 66, origin.y + 73, 160, 22);
		setRendered(true);
		return new Dimension(WIDTH, HEIGHT);
	}

	private void drawPanel(Graphics2D graphics)
	{
		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(0, 0, WIDTH, HEIGHT, 8, 8);

		Stroke stroke = graphics.getStroke();
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(BORDER_DARK);
		graphics.drawRoundRect(0, 0, WIDTH - 1, HEIGHT - 1, 8, 8);
		graphics.setStroke(new BasicStroke(1));
		graphics.setColor(BORDER_LIGHT);
		graphics.drawRoundRect(2, 2, WIDTH - 5, HEIGHT - 5, 6, 6);
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(BORDER_DARK);
		graphics.drawLine(2, HEADER_HEIGHT, WIDTH - 3, HEADER_HEIGHT);
		graphics.setStroke(new BasicStroke(1));
		graphics.setColor(BORDER_LIGHT);
		graphics.drawLine(3, HEADER_HEIGHT + 1, WIDTH - 4, HEADER_HEIGHT + 1);
		graphics.setStroke(stroke);

		drawCenteredText(graphics, "Tip from Visual Bank Tags", new Rectangle(0, 0, WIDTH, HEADER_HEIGHT), TITLE);
		drawText(graphics, "You can right-click the bank options", 13, 48, TEXT);
		drawText(graphics, "to toggle bank visuals.", 13, 64, TEXT);
		drawCloseButton(graphics);
	}

	private void drawBankButtonPulse(Graphics2D graphics)
	{
		Widget button = client.getWidget(InterfaceID.Bankmain.MENU_BUTTON);
		if (button == null || button.isHidden())
		{
			return;
		}

		Rectangle bounds = button.getBounds();
		Rectangle overlayBounds = getBounds();
		int alpha = 120 + (int) (80 * (0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 180.0)));
		Rectangle localButton = new Rectangle(bounds.x - overlayBounds.x, bounds.y - overlayBounds.y, bounds.width, bounds.height);
		Rectangle pulseBounds = new Rectangle(localButton.x - 5, localButton.y - 5, localButton.width + 9, localButton.height + 9);
		Point2D target = nearestCorner(pulseBounds, new Point2D.Double(WIDTH / 2.0, HEIGHT / 2.0));
		double targetX = target.getX();
		double targetY = target.getY();
		double sourceX = Math.max(0, Math.min(WIDTH, targetX));
		double sourceY = Math.max(0, Math.min(HEIGHT, targetY));
		Stroke stroke = graphics.getStroke();
		graphics.setStroke(new BasicStroke(6, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), Math.max(25, alpha / 4)));
		graphics.draw(new Line2D.Double(sourceX, sourceY, targetX, targetY));
		graphics.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), alpha));
		graphics.draw(new Line2D.Double(sourceX, sourceY, targetX, targetY));
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), alpha));
		graphics.drawRect(localButton.x - 2, localButton.y - 2, localButton.width + 3, localButton.height + 3);
		graphics.drawRect(pulseBounds.x, pulseBounds.y, pulseBounds.width, pulseBounds.height);
		graphics.setStroke(stroke);
	}

	private void drawCloseButton(Graphics2D graphics)
	{
		graphics.setColor(BUTTON);
		graphics.fillRect(66, 73, 160, 22);
		graphics.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 0xDD));
		graphics.drawRect(66, 73, 160, 22);
		graphics.setColor(BORDER_LIGHT);
		graphics.drawRect(68, 75, 156, 18);
		drawCenteredText(graphics, "Never show this again", new Rectangle(66, 73, 160, 22), TEXT);
	}

	private Point2D nearestCorner(Rectangle bounds, Point2D target)
	{
		Point2D best = new Point2D.Double(bounds.x, bounds.y);
		double bestDistance = best.distanceSq(target);
		Point2D[] corners = {
			new Point2D.Double(bounds.x + bounds.width, bounds.y),
			new Point2D.Double(bounds.x, bounds.y + bounds.height),
			new Point2D.Double(bounds.x + bounds.width, bounds.y + bounds.height)
		};
		for (Point2D corner : corners)
		{
			double distance = corner.distanceSq(target);
			if (distance < bestDistance)
			{
				best = corner;
				bestDistance = distance;
			}
		}
		return best;
	}

	private void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	private void drawCenteredText(Graphics2D graphics, String text, Rectangle bounds, Color color)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		int y = bounds.y + ((bounds.height - metrics.getHeight()) / 2) + metrics.getAscent();
		drawText(graphics, text, x, y, color);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (!rendered)
		{
			return event;
		}

		if (panelBounds.contains(event.getPoint()))
		{
			event.consume();
			return event;
		}

		return event;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (!SwingUtilities.isLeftMouseButton(event) || !rendered)
		{
			return event;
		}

		Point point = event.getPoint();
		if (closeButtonBounds.contains(point))
		{
			plugin.hideToggleTipForever();
			setRendered(false);
			event.consume();
			return event;
		}
		if (titleBarBounds.contains(point))
		{
			dragging = true;
			Point location = getPreferredLocation();
			if (location == null)
			{
				location = panelBounds.getLocation();
			}
			dragOffset = new Point(point.x - location.x, point.y - location.y);
			event.consume();
			return event;
		}
		if (panelBounds.contains(point))
		{
			event.consume();
			return event;
		}

		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (dragging)
		{
			dragging = false;
			event.consume();
			return event;
		}

		return event;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (dragging)
		{
			Point point = event.getPoint();
			setPreferredLocation(new Point(point.x - dragOffset.x, point.y - dragOffset.y));
			event.consume();
			return event;
		}

		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		return event;
	}

	private void setRendered(boolean rendered)
	{
		this.rendered = rendered;
		if (!rendered)
		{
			dragging = false;
			panelBounds = new Rectangle();
			titleBarBounds = new Rectangle();
			closeButtonBounds = new Rectangle();
		}
	}
}

